message.content:
{
  "description": "The creature is shown in a three-quarter front-side view facing to the right, standing on a flat light surface with a faint shadow under its feet. It has a stout, low-slung, quadrupedal body with an arched back and a thick tapering tail extending to the left and partially out of frame. The dorsal surface from the back of the neck over the back and onto the base of the tail is covered in overlapping large rounded scales that are dark brown-gray in the center with lighter tan edges, arranged in diagonal rows. The ventral body, head, limbs, and underside of the tail are pale pinkish-beige with wrinkled, smooth, fleshy skin showing horizontal folds along the torso and limbs. The head at the front right is broad, flat and blunt-snouted with large round dark eyes with pale irises, small nostrils, and a wide slightly upturned mouth. Six feathery pink to reddish external gills with fine filamentous branches project from the sides of the head and neck, three per side. The four limbs are thick and columnar, splayed slightly outward, ending in broad five-toed feet with small dark claws.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, flat, blunt-snouted, pale pink-beige with smooth skin and faint darker mottling, large round dark eyes with light blue-gray irises, small round nostrils near the tip of the snout, and a wide mouth with a slight smile",
      "where": "at the front right of the body, facing to the right, connected to the scaled back at the neck"
    },
    {
      "part": "gills",
      "looks_like": "six feathery external gill stalks, pink to reddish, each stalk with many fine hair-like filaments along its length, fleshy at the base and tapering",
      "where": "three on each side of the head/neck just behind the jaw, projecting outward and slightly backward"
    },
    {
      "part": "scales",
      "looks_like": "large overlapping rounded keratinous scales/plates, dark brown-gray centers with lighter tan rims and fine radial lines, arranged in neat diagonal rows like armor",
      "where": "covering the entire dorsal side from the back of the neck over the arched back and down the sides to the belly fold, and continuing onto the dorsal base of the tail"
    },
    {
      "part": "legs",
      "looks_like": "four stout, columnar, fleshy limbs with wrinkled pale pink skin, loose folds at the joints, slightly bent at the elbows and knees",
      "where": "two forelimbs under the chest and two hindlimbs under the mid-body, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "broad flat feet with five short splayed digits each, tipped with small dark pointed claws, pale pink with wrinkled skin",
      "where": "at the distal ends of each of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "thick at the base and tapering toward the tip, dorsal side covered in the same overlapping scales as the back, ventral and lateral sides pale wrinkled skin",
      "where": "extending to the left rear from the back of the body, partially cropped by the edge of the image"
    }
  ],
  "attached_objects": [],
  "animals": ["axolotl", "pangolin"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
